      // Landing - FAQ
      "landing.faq.title": "Questions fréquentes",
      "landing.faq.subtitle": "Tout ce que tu dois savoir avant de commencer",
      "landing.faq.q1": "C'est quoi Travliaq exactement ?",
      "landing.faq.a1": "Travliaq est ton assistant voyage IA personnel. Tu lui dis où tu veux aller, ton budget, tes dates, et il te crée un itinéraire sur-mesure avec vols, hôtels et activités. Tout ça en quelques minutes au lieu de plusieurs heures.",
      "landing.faq.q2": "C'est gratuit ?",
      "landing.faq.a2": "Oui, la planification de base est gratuite ! Tu peux créer des itinéraires et obtenir des recommandations sans frais. Des options premium sont disponibles pour plus de fonctionnalités comme le téléchargement PDF ou la personnalisation avancée.",
      "landing.faq.q3": "Comment ça marche concrètement ?",
      "landing.faq.a3": "Tu discutes avec moi comme avec un ami. Tu me dis tes envies (destination, dates, budget, style de voyage) et je te propose un itinéraire complet. Tu peux affiner, modifier, et quand tu es satisfait, tu reçois tout par email.",
      "landing.faq.q4": "Je peux modifier mon itinéraire après ?",
      "landing.faq.a4": "Absolument ! Tu peux revenir dessus à tout moment. Change les dates, ajoute des activités, modifie l'hôtel... Je m'adapte en temps réel à tes demandes.",
      "landing.faq.q5": "Les prix sont-ils fiables ?",
      "landing.faq.a5": "Je compare les prix en temps réel avec les principales plateformes de réservation. Les prix affichés sont ceux que tu retrouveras au moment de la réservation (aux variations normales près).",
      "landing.faq.q6": "Quelles destinations sont disponibles ?",
      "landing.faq.a6": "Travliaq couvre le monde entier ! Que tu rêves de Tokyo, New York, Marrakech, Bali ou d'un road trip en Patagonie, notre IA trouve les meilleures options pour n'importe quelle destination.",
      "landing.faq.q7": "Combien de temps faut-il pour recevoir mon itinéraire ?",
      "landing.faq.a7": "En général, tu reçois ta première proposition dans les 24 heures suivant ta demande. Pour les demandes urgentes, nous pouvons accélérer le processus.",
      "landing.faq.q8": "Puis-je voyager en groupe ou en famille ?",
      "landing.faq.a8": "Bien sûr ! Travliaq s'adapte à tous les types de voyageurs : solo, duo, groupe d'amis ou famille avec enfants. L'itinéraire sera personnalisé en fonction du nombre de participants et de leurs besoins spécifiques.",
      "landing.faq.q9": "Comment mes données sont-elles protégées ?",
      "landing.faq.a9": "Tes données sont sécurisées et ne sont jamais partagées avec des tiers sans ton consentement. Nous utilisons les meilleures pratiques de sécurité et respectons le RGPD.",
      "landing.faq.q10": "Comment contacter le support ?",
      "landing.faq.a10": "Tu peux nous contacter à tout moment via contact@travliaq.com. Notre équipe répond généralement sous 24h. Tu peux aussi utiliser le chat intégré pour des questions rapides.",

