      "landing.faq.title": "Frequently asked questions",
      "landing.faq.subtitle": "Everything you need to know before getting started",
      "landing.faq.q1": "What exactly is Travliaq?",
      "landing.faq.a1": "Travliaq is your personal AI travel assistant. Tell it where you want to go, your budget, your dates, and it creates a custom itinerary with flights, hotels and activities. All in minutes instead of hours.",
      "landing.faq.q2": "Is it free?",
      "landing.faq.a2": "Yes, basic planning is free! You can create itineraries and get recommendations at no cost. Premium options are available for more features like PDF downloads or advanced customization.",
      "landing.faq.q3": "How does it work exactly?",
      "landing.faq.a3": "You chat with me like with a friend. Tell me your wishes (destination, dates, budget, travel style) and I'll suggest a complete itinerary. You can refine, modify, and when you're satisfied, you receive everything by email.",
      "landing.faq.q4": "Can I modify my itinerary afterwards?",
      "landing.faq.a4": "Absolutely! You can come back to it anytime. Change dates, add activities, modify the hotel... I adapt in real-time to your requests.",
      "landing.faq.q5": "Are the prices reliable?",
      "landing.faq.a5": "I compare prices in real-time with major booking platforms. The displayed prices are what you'll find when booking (subject to normal variations).",
      "landing.faq.q6": "Which destinations are available?",
      "landing.faq.a6": "Travliaq covers the entire world! Whether you dream of Tokyo, New York, Marrakech, Bali or a road trip in Patagonia, our AI finds the best options for any destination.",
      "landing.faq.q7": "How long does it take to receive my itinerary?",
      "landing.faq.a7": "Generally, you receive your first proposal within 24 hours of your request. For urgent requests, we can speed up the process.",
      "landing.faq.q8": "Can I travel in a group or with family?",
      "landing.faq.a8": "Of course! Travliaq adapts to all types of travelers: solo, duo, group of friends or family with children. The itinerary will be customized based on the number of participants and their specific needs.",
      "landing.faq.q9": "How is my data protected?",
      "landing.faq.a9": "Your data is secure and never shared with third parties without your consent. We use best security practices and comply with GDPR.",
      "landing.faq.q10": "How do I contact support?",
      "landing.faq.a10": "You can contact us anytime at contact@travliaq.com. Our team typically responds within 24 hours. You can also use the integrated chat for quick questions.",

